-- Auditoria jurídica refeita: PF 2021 (Agente). Textos oficiais compilados do Planalto e súmulas conferidos em 27/09/2026.

update public.official_exam_questions set review_note=$q$Conferido no texto compilado da Lei 8.112/1990 (Planalto, 27/09/2026): art. 132, IX, comina demissão para a revelação de segredo do qual o servidor se apropriou em razão do cargo. Gabarito C confere.$q$, question_text=$q$Texto-base:
Determinado agente da Polícia Federal revelou um segredo sobre uma operação policial que seria realizada para deter uma quadrilha de traficantes. Ele havia se apropriado desse segredo em razão do seu cargo. Tendo a operação fracassado, a administração da Polícia recebeu uma denúncia sobre o ocorrido e abriu processo administrativo disciplinar contra o referido servidor.
Considerando essa situação hipotética, julgue os itens subsequentes.

Item: O servidor, em razão do seu ato, está sujeito à pena de demissão.$q$, context_review_required=false, content_status='active', current_syllabus_topic_id=(select t.id from public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id where e.contest_name=$q$Polícia Federal$q$ and e.contest_year=2025 and e.role_name=$q$Agente de Polícia Federal$q$ and t.discipline=$q$Noções de Direito Administrativo$q$ and t.topic_order=2 and t.block_name not ilike '%Hist%' limit 1), legal_audit_completed=true, legal_review_required=false, legal_basis=jsonb_build_array(jsonb_build_object('title',$q$Lei nº 8.112/1990 – texto compilado$q$,'url',$q$https://www.planalto.gov.br/ccivil_03/leis/l8112compilado.htm$q$)), law_version_checked_at=now() where exam_year=2021 and career_name=$q$Agente de Polícia Federal$q$ and item_number=25 and content_status='under_review';
-- @@
update public.official_exam_questions set review_note=$q$Bloqueado (27/09/2026): o item depende do conceito doutrinário de poder disciplinar x poder de polícia, sem texto legal que o defina; a governança exige fonte oficial vigente. A chave oficial (E) continua valendo para a pontuação.$q$ where exam_year=2021 and career_name=$q$Agente de Polícia Federal$q$ and item_number=26 and content_status='under_review';
-- @@
update public.official_exam_questions set review_note=$q$Conferido (Planalto, 27/09/2026): a CF, arts. 70 e 74, distingue controle externo (Congresso/TCU) de controle interno de cada Poder; a instauração de processo disciplinar pela própria Administração é controle interno, ligado ao dever de apuração (Lei 8.112, art. 143) e à autotutela (Lei 9.784, art. 53). Gabarito E confere.$q$, question_text=$q$Texto-base:
Determinado agente da Polícia Federal revelou um segredo sobre uma operação policial que seria realizada para deter uma quadrilha de traficantes. Ele havia se apropriado desse segredo em razão do seu cargo. Tendo a operação fracassado, a administração da Polícia recebeu uma denúncia sobre o ocorrido e abriu processo administrativo disciplinar contra o referido servidor.
Considerando essa situação hipotética, julgue os itens subsequentes.

Item: A abertura do processo contra o servidor em questão é considerada controle externo e posterior.$q$, context_review_required=false, content_status='active', current_syllabus_topic_id=(select t.id from public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id where e.contest_name=$q$Polícia Federal$q$ and e.contest_year=2025 and e.role_name=$q$Agente de Polícia Federal$q$ and t.discipline=$q$Noções de Direito Administrativo$q$ and t.topic_order=3 and t.block_name not ilike '%Hist%' limit 1), legal_audit_completed=true, legal_review_required=false, legal_basis=jsonb_build_array(jsonb_build_object('title',$q$Constituição Federal de 1988 – texto compilado$q$,'url',$q$https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm$q$),jsonb_build_object('title',$q$Lei nº 9.784/1999$q$,'url',$q$https://www.planalto.gov.br/ccivil_03/leis/l9784.htm$q$)), law_version_checked_at=now() where exam_year=2021 and career_name=$q$Agente de Polícia Federal$q$ and item_number=27 and content_status='under_review';
-- @@
update public.official_exam_questions set review_note=$q$Conferido no texto compilado da CF (Planalto, 27/09/2026): art. 5º, XLIII, torna inafiançável o tráfico ilícito de entorpecentes e drogas afins. Gabarito C confere.$q$, question_text=$q$Comando:
A polícia foi acionada para atender a um chamado de suspeita de ocorrência de tráfico ilícito de entorpecentes no interior de determinada sociedade de economia mista federal. Ao chegar ao local, os policiais verificaram que um dos traficantes era um brasileiro naturalizado.
Considerando essa situação hipotética, julgue os itens subsecutivos.

Item: O tráfico ilícito de entorpecentes é crime inafiançável.$q$, context_review_required=false, content_status='active', current_syllabus_topic_id=(select t.id from public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id where e.contest_name=$q$Polícia Federal$q$ and e.contest_year=2025 and e.role_name=$q$Agente de Polícia Federal$q$ and t.discipline=$q$Noções de Direito Constitucional$q$ and t.topic_order=1 and t.block_name not ilike '%Hist%' limit 1), legal_audit_completed=true, legal_review_required=false, legal_basis=jsonb_build_array(jsonb_build_object('title',$q$Constituição Federal de 1988 – texto compilado$q$,'url',$q$https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm$q$)), law_version_checked_at=now() where exam_year=2021 and career_name=$q$Agente de Polícia Federal$q$ and item_number=29 and content_status='under_review';
-- @@
update public.official_exam_questions set review_note=$q$Conferido no texto compilado da CF (Planalto, 27/09/2026): art. 5º, LI, permite extraditar o naturalizado por crime comum anterior à naturalização OU por comprovado envolvimento em tráfico de drogas; portanto o item, que só invoca a data do crime, é errado. Gabarito E confere.$q$, question_text=$q$Comando:
A polícia foi acionada para atender a um chamado de suspeita de ocorrência de tráfico ilícito de entorpecentes no interior de determinada sociedade de economia mista federal. Ao chegar ao local, os policiais verificaram que um dos traficantes era um brasileiro naturalizado.
Considerando essa situação hipotética, julgue os itens subsecutivos.

Item: O traficante naturalizado brasileiro não poderá ser extraditado porque o crime foi praticado depois da naturalização.$q$, context_review_required=false, content_status='active', current_syllabus_topic_id=(select t.id from public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id where e.contest_name=$q$Polícia Federal$q$ and e.contest_year=2025 and e.role_name=$q$Agente de Polícia Federal$q$ and t.discipline=$q$Noções de Direito Constitucional$q$ and t.topic_order=1 and t.block_name not ilike '%Hist%' limit 1), legal_audit_completed=true, legal_review_required=false, legal_basis=jsonb_build_array(jsonb_build_object('title',$q$Constituição Federal de 1988 – texto compilado$q$,'url',$q$https://www.planalto.gov.br/ccivil_03/constituicao/constituicaocompilado.htm$q$)), law_version_checked_at=now() where exam_year=2021 and career_name=$q$Agente de Polícia Federal$q$ and item_number=30 and content_status='under_review';
