update public.official_exam_questions set review_note=$q$Conferido no texto compilado do CPP (Planalto, 27/09/2026): art. 158-B, V, define acondicionamento como o ato de embalar individualmente o vestígio; armazenamento (art. 158-B, IX) é a guarda em condições adequadas. Gabarito E confere.$q$, question_text=$q$Comando:
    Com relação ao direito penal e ao direito processual penal, julgue
    os itens que se seguem.

Item: Armazenamento consiste no procedimento de embalar, de forma individualizada, cada vestígio coletado, de acordo com suas características físicas, químicas e biológicas, para análise posterior.$q$, context_review_required=false, content_status='active', current_syllabus_topic_id=(select t.id from public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id where e.contest_name=$q$Polícia Federal$q$ and e.contest_year=2025 and e.role_name=$q$Agente de Polícia Federal$q$ and t.discipline=$q$Direito Penal e Processual Penal$q$ and t.topic_order=4 and t.block_name not ilike '%Hist%' limit 1), legal_audit_completed=true, legal_review_required=false, legal_basis=jsonb_build_array(jsonb_build_object('title',$q$Código de Processo Penal – texto compilado$q$,'url',$q$https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm$q$)), law_version_checked_at=now() where exam_year=2021 and career_name=$q$Agente de Polícia Federal$q$ and item_number=31 and content_status='under_review';
