update public.official_exam_questions set review_note=$q$Conferido (27/09/2026): Lei 11.343/2006, art. 40, I (transnacionalidade), e Súmula 607 do STJ, no repositório do tribunal: a majorante se configura com a prova da destinação internacional das drogas, ainda que não consumada a transposição da fronteira. Gabarito E confere.$q$, question_text=$q$Comando:
    Cada um dos itens a seguir apresenta uma situação hipotética
    seguida de uma assertiva a ser julgada. Julgue-os com base na
    legislação especial.

Item: Determinada pessoa foi presa em flagrante delito, porque estava, no território brasileiro, próximo à região de fronteira com determinado país da América do Sul, transportando uma grande quantidade de drogas. Nessa situação, a configuração do tráfico transnacional depende da comprovação da transposição da fronteira, hipótese em que a pena poderá aumentar.$q$, context_review_required=false, content_status='active', current_syllabus_topic_id=(select t.id from public.syllabus_topics t join public.syllabus_editions e on e.id=t.edition_id where e.contest_name=$q$Polícia Federal$q$ and e.contest_year=2025 and e.role_name=$q$Agente de Polícia Federal$q$ and t.discipline=$q$Legislação Especial$q$ and t.topic_order=2 and t.block_name not ilike '%Hist%' limit 1), legal_audit_completed=true, legal_review_required=false, legal_basis=jsonb_build_array(jsonb_build_object('title',$q$Lei nº 11.343/2006 – Lei de Drogas$q$,'url',$q$https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2006/lei/l11343.htm$q$),jsonb_build_object('title',$q$STJ – Súmula 607$q$,'url',$q$https://scon.stj.jus.br/SCON/pesquisar.jsp?b=SUMU&sumula=607$q$)), law_version_checked_at=now() where exam_year=2021 and career_name=$q$Agente de Polícia Federal$q$ and item_number=34 and content_status='under_review';
-- @@
update public.official_exam_questions set review_note=$q$Conferido no texto compilado da Lei 13.445/2017 (Planalto, 27/09/2026): art. 54, caput e §4º, prevê impedimento de reingresso por prazo determinado, proporcional à pena e nunca superior ao dobro dela. Gabarito E confere.$q$, question_text=$q$Comando:
    Cada um dos itens a seguir apresenta uma situação hipotética
    seguida de uma assertiva a ser julgada. Julgue-os com base na
    legislação especial.

